import{_ as o,o as t,c as a,a5 as r}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"FR 3.6.7 — Kanban Board Task View","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/05-content-task-workflow/3-6-7-kanban-board-task-view/spec.md","filePath":"feature/srs/05-content-task-workflow/3-6-7-kanban-board-task-view/spec.md"}'),s={name:"feature/srs/05-content-task-workflow/3-6-7-kanban-board-task-view/spec.md"};function n(c,e,i,d,l,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-6-7-—-kanban-board-task-view" tabindex="-1">FR 3.6.7 — Kanban Board Task View <a class="header-anchor" href="#fr-3-6-7-—-kanban-board-task-view" aria-label="Permalink to &quot;FR 3.6.7 — Kanban Board Task View&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.6.7</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-059</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">Kanban Board Task View</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">Content &amp; Workflow (<code>FR 3.6</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-33, BR-34</code></td></tr><tr><td style="text-align:left;"><strong>Document Status</strong></td><td style="text-align:left;">Implemented &amp; Verified</td></tr></tbody></table><h2 id="_1-objective-functional-scope" tabindex="-1">1. Objective &amp; Functional Scope <a class="header-anchor" href="#_1-objective-functional-scope" aria-label="Permalink to &quot;1. Objective &amp; Functional Scope&quot;">​</a></h2><p>Xem và kéo thả trạng thái công việc trên bảng Kanban kiểu Jira (Kanban Board Task View — /workspaces/:id/tasks?view=kanban). Hỗ trợ chuyển đổi linh hoạt theo 3 chế độ nhóm cột (Group by Status: Backlog / In Progress / In Review / Approved / Published; Group by Assignee; Group by Platform) và kéo thả thẻ Task để cập nhật trạng thái tuân thủ quy trình duyệt (BR-33, BR-34).</p><p><strong>Consolidated Implementation Scope:</strong> Groups Workspace Tasks into workflow status columns (<code>TODO</code>, <code>IN_PROGRESS</code>, <code>IN_REVIEW</code>, <code>FINISHED</code>, <code>CANCELLED</code>) sharing active filter/search state with List/Calendar/Timeline views (<code>BR-33</code>), enforcing state-machine guards (<code>BR-34</code>: preventing unauthorized drag-bypass of <code>Manager</code>/<code>Client</code> approval gates).</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an authorized actor (<code>Owner, Manager, Creator, Client</code>), I want to execute <strong>Kanban Board Task View</strong> within my active Workspace with strict role/audience isolation, version/concurrency safety, and responsive feedback, so that content production workflows satisfy <code>BR-33, BR-34</code> across Web and Mobile.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Workspace &amp; Role Authorization:</strong> Only authenticated actors holding <code>Owner, Manager, Creator, Client</code> in the target Workspace (plus <code>Guest</code> solely on public survey token endpoints in <code>3.6.25</code>) may invoke <code>GET /api/v1/workspaces/{workspaceId}/tasks · PATCH /api/v1/workspaces/{workspaceId}/tasks/{taskId}/status</code>; revoked or cross-workspace callers are rejected (<code>401</code> / <code>403</code>).</li><li><strong>Core Domain &amp; Security Invariants (<code>BR-33, BR-34</code> — Anti-Bypass Guard):</strong> <code>TaskServiceImpl, TaskWorkflowService, TaskApprovalService</code> enforces all state-machine locks, audience visibility filters (<code>INTERNAL</code> vs per-<code>clientProfileId</code> <code>CLIENT</code>), storage/file validation rules, and Workspace timezone boundaries (<code>Asia/Ho_Chi_Minh</code> default). Specifically: <ul><li><strong>Strict Approval Anti-Bypass:</strong> Neither <code>Creator</code>, <code>Manager</code>, nor <code>Owner</code> may drag a card directly into <code>IN_REVIEW</code> or <code>FINISHED</code> via <code>PATCH /tasks/{taskId}/status</code> (<code>409 TASK_WORKFLOW_REQUIRED</code>); transitioning to <code>IN_REVIEW</code> or <code>FINISHED</code> requires executing the formal submission and approval workflow (<a href="./../3-6-9-approval-sequence-creator-manager-client/spec.html">FR 3.6.9</a>).</li><li><strong>Cancellation Restriction:</strong> Dragging or changing status to <code>CANCELLED</code> is strictly restricted to <code>Owner</code> and <code>Manager</code> (<code>Creator</code> receives <code>403 FORBIDDEN</code>), recording <code>Cancellation</code> audit metadata and revoking any scheduled post publication.</li><li><strong>Instant Cross-View Sync:</strong> Approving or returning sections/tasks inside <code>TaskDetailPanel</code> immediately refreshes the Kanban board column placement without requiring a manual page reload.</li></ul></li><li><strong>Persistence &amp; Envelope Contract:</strong> Operations on MongoDB <code>tasks</code> (<code>status</code>: <code>TODO</code>/<code>BACKLOG</code>, <code>IN_PROGRESS</code>, <code>IN_REVIEW</code>, <code>FINISHED</code>, <code>CANCELLED</code>) return standardized <code>ApiResponse&lt;T&gt;</code> payloads (or authenticated binary/WebSocket frames where applicable) with deterministic <code>ErrorCode</code> mappings (<code>400 INVALID_STATUS_TRANSITION</code>, <code>403 FORBIDDEN</code>, <code>409 TASK_WORKFLOW_REQUIRED</code> (<code>BR-33</code>, <code>BR-34</code>)).</li><li><strong>Internationalization (<code>vi</code> / <code>en</code>):</strong> Every label, badge, filter pill, modal prompt, empty state, and error toast uses parallel translation keys (<code>tasks.board.* / tasks.status.*</code>) in <code>src/i18n/locales/vi/*.json</code> and <code>en/*.json</code> — zero hardcoded UI text.</li><li><strong>Semantic Light/Dark Theme &amp; Accessibility:</strong> Web (<code>src/pages/tasks/index.tsx</code>, <code>src/pages/tasks/components/views/BoardView.tsx</code>, <code>src/pages/tasks/components/views/hooks/{useBoardColumns,useBoardDragAndDrop}.ts</code>) and Mobile (<code>src/screens/content/TaskKanbanScreen.tsx</code>, <code>src/services/taskService.ts</code>) components use semantic CSS variables / <code>dark:</code> Tailwind tokens and <code>useTheme()</code> tokens, supporting keyboard navigation (<code>Enter</code>/<code>Escape</code>/focus return) and mobile viewports.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surface (<code>brandhub-web</code>):</strong> <code>src/pages/tasks/index.tsx</code>, <code>src/pages/tasks/components/views/BoardView.tsx</code>, <code>src/pages/tasks/components/views/hooks/{useBoardColumns,useBoardDragAndDrop}.ts</code></li><li><strong>Mobile Surface (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/content/TaskKanbanScreen.tsx</code>, <code>src/services/taskService.ts</code></li><li><strong>Required UI States:</strong><ul><li><strong>Loading / Pending:</strong> Skeleton placeholders, progress indicators for uploads/imports, and disabled duplicate-submit triggers.</li><li><strong>Empty State:</strong> Clear localized explanation with role-appropriate CTA — never substituting synthetic mock items.</li><li><strong>Conflict / Warning:</strong> Preserves unsaved user drafts on <code>409</code> conflicts and surfaces inline warnings (such as <code>RAW</code> unedited photo badges or compliance warnings).</li><li><strong>Error / Retry:</strong> Actionable inline/banner error state with retry capability.</li></ul></li></ul><h2 id="_5-api-realtime-contract" tabindex="-1">5. API &amp; Realtime Contract <a class="header-anchor" href="#_5-api-realtime-contract" aria-label="Permalink to &quot;5. API &amp; Realtime Contract&quot;">​</a></h2><ul><li><strong>Endpoints / Channels:</strong> <code>GET /api/v1/workspaces/{workspaceId}/tasks · PATCH /api/v1/workspaces/{workspaceId}/tasks/{taskId}/status</code></li><li><strong>Controllers (<code>brandhub-business-service</code>):</strong> <code>TaskController.getTasks() / updateStatus(), TaskWorkflowController.start(), TaskApprovalController</code></li><li><strong>Services:</strong> <code>TaskServiceImpl, TaskWorkflowService, TaskApprovalService</code></li><li><strong>Repositories / Stores:</strong> TaskMongoRepository (MongoDB <code>tasks</code>)</li></ul><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Domain Error Codes:</strong> <code>400 INVALID_STATUS_TRANSITION</code>, <code>403 FORBIDDEN</code>, <code>409 TASK_WORKFLOW_REQUIRED</code> (<code>BR-33</code>, <code>BR-34</code>).</li><li><strong>Audience &amp; Removed-Member Isolation:</strong> Removed or deactivated Workspace members lose read/write/WebSocket access immediately on the next request or STOMP frame; <code>Client</code> actors never see <code>INTERNAL</code>-only materials or other <code>ClientProfile</code> assets.</li><li><strong>Idempotency &amp; Concurrency:</strong> Optimistic revision checks (<code>workflowRevision</code>, <code>revision</code>, <code>clientMessageId</code>, <code>DriveOperationLease</code>) prevent race-condition overwrites and duplicate records on retry.</li></ul><h2 id="_7-definition-of-done-cross-references" tabindex="-1">7. Definition of Done &amp; Cross-References <a class="header-anchor" href="#_7-definition-of-done-cross-references" aria-label="Permalink to &quot;7. Definition of Done &amp; Cross-References&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Backend endpoints/handlers verified by automated tests (<a href="./test.html">test.md</a>), Web &amp; Mobile UI integrated against live APIs, <code>vi</code>/<code>en</code> locale parity verified, and Light/Dark themes verified.</li><li><strong>Out of Scope:</strong> Adjacent workflow capabilities covered by sibling FRs in <code>3.6.1–3.6.35</code> and social publishing execution in <code>3.8.1–3.8.15</code>.</li><li><strong>Related Documentation:</strong> <a href="./../../../../ba/05-content-task-workflow.html">BA Content &amp; Workflow Spec</a> · <a href="./../../../../ba/12-state-machines.html">State Machines</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a> · <a href="./test.html">Test Suite</a>.</li></ul>',18)])])}const h=o(s,[["render",n]]);export{u as __pageData,h as default};
